  /// produces the escape bytes — XCUITest cannot type an ESC into a PTY directly.
  private func run(_ app: XCUIApplication, _ line: String) {
    app.typeText(line + "\r")
  }

  /// A tab chip by title. The chip carries `terminal.tab.<title>`, so the identifier IS the
  /// assertion — the title only becomes part of it once `SET_TITLE` has landed.
  private func tabChip(_ app: XCUIApplication, title: String) -> XCUIElement {
    app.descendants(matching: .any).matching(identifier: "terminal.tab.\(title)").firstMatch
  }

  // MARK: GHOSTTY_ACTION_SET_TITLE

  /// OSC 0 sets the tab title. Proves `SET_TITLE` → `handleTitleChange` → `updateTitle` →
  /// `tab.liveTitle` → the chip.
  ///
  /// The title is deliberately not a path: `TerminalSessions.updateTitle` drops directory titles
  /// (issue #2), so a path-shaped title would be filtered and the test would fail for the wrong
  /// reason.
  func testOSCTitleUpdatesTheTabChip() {
    let app = launchedApp()
    focusTerminal(app)
    run(app, #"printf '\033]0;wr-osc-title\007'"#)

    XCTAssertTrue(
      tabChip(app, title: "wr-osc-title").waitForExistence(timeout: 20),
      "OSC 0 reached GHOSTTY_ACTION_SET_TITLE and renamed the tab")
  }

  // MARK: GHOSTTY_ACTION_PROGRESS_REPORT

  /// OSC 9;4 drives the tab's busy state (issue #28). The chip's accessibility VALUE is the only
  /// non-visual carrier of it — the underline is drawn, not announced.
  ///
  /// Asserts both edges: state 1 (set) marks it busy, state 0 (remove) clears it. The clear half
  /// matters most — a stuck spinner is the failure users actually report.
  func testOSCProgressReportMarksTheTabBusyThenIdle() {
    let app = launchedApp()
    focusTerminal(app)

    // Title the tab first so the chip has a stable identifier to query through the state changes.
    run(app, #"printf '\033]0;wr-progress\007'"#)
    let chip = tabChip(app, title: "wr-progress")
    XCTAssertTrue(chip.waitForExistence(timeout: 20), "the tab is addressable")

    run(app, #"printf '\033]9;4;1;50\007'"#)
    XCTAssertTrue(
      waitForValue(chip, "Busy"),
      "OSC 9;4 state 1 reached GHOSTTY_ACTION_PROGRESS_REPORT and marked the tab busy")

    run(app, #"printf '\033]9;4;0;0\007'"#)
