  /// Deliberately asserts the counter CHANGES rather than exact indices: the echoed command line is
  /// itself a match, so the total depends on shell echo and wrapping. What must hold is that both
  /// actions arrive and move the display; the arithmetic is unit-tested in `TerminalSearchTests`.
  func testScrollbackSearchCountersArrive() {
    let app = launchedApp()
    focusTerminal(app)
    run(app, "printf 'wrneedle\\nwrneedle\\nwrneedle\\n'")

    app.typeKey("f", modifierFlags: .command)
    let summary = app.staticTexts["terminal.search.summary"]
    XCTAssertTrue(summary.waitForExistence(timeout: 15), "⌘F opened the find bar")

    app.typeText("wrneedle")
    XCTAssertTrue(
      waitForMatchCount(summary),
      "GHOSTTY_ACTION_SEARCH_TOTAL delivered a match count, got \(summary.label)")
