  /// The summary reads "n/total" once the engine reports matches, "No results" when it reports none,
  /// and "" before the needle is set.
  private func waitForMatchCount(_ element: XCUIElement, timeout: TimeInterval = 15) -> Bool {
    poll(timeout: timeout) { element.label.contains("/") }
  }

  private func waitForChange(
    _ element: XCUIElement, from previous: String, timeout: TimeInterval = 15
  ) -> Bool {
    poll(timeout: timeout) { element.label != previous && element.label.contains("/") }
  }

  private func poll(timeout: TimeInterval, until condition: () -> Bool) -> Bool {
    let deadline = Date().addingTimeInterval(timeout)
    while Date() < deadline {
      if condition() { return true }
      RunLoop.current.run(until: Date().addingTimeInterval(0.25))
    }
    return condition()
  }
}

